    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, 'A 82-year-old male named John with advanced dementia (FAST stage 7c) is admitted to the hospital with a third episode of aspiration pneumonia in the past 3 months. His son is highly distressed, noting that the patient is eating very little, and asks about placing a percutaneous endoscopic gastrostomy (PEG) feeding tube. According to the American Geriatrics Society (AGS) guidelines, which of the following is the most appropriate counseling and clinical recommendation?', '["Recommend immediate PEG tube placement to prevent malnutrition, as feeding tubes have been shown to significantly prolong life and prevent decubitus ulcers in advanced dementia", "Recommend a temporary nasogastric (NG) tube for 6 months to see if he recovers his baseline cognitive function and swallowing capacity", "Suggest starting total parenteral nutrition (TPN) through a central line as a safer and more effective alternative to tube feeding in advanced dementia", "Recommend continuing careful hand-feeding and comfort-focused care; explain that PEG tube placement in advanced dementia does not prolong survival, reduce the risk of aspiration pneumonia, improve nutritional parameters, or enhance patient comfort", "Advise the family that a PEG tube is legally mandatory once a patient with dementia is unable to meet their daily caloric needs orally"]'::jsonb, 3, 'For patients with advanced dementia (FAST stage 7), clinical evidence demonstrates that **percutaneous endoscopic gastrostomy (PEG) feeding tubes do not prolong survival, reduce aspiration risk, improve nutritional status, or enhance comfort**. Feeding tubes are associated with significant complications, including local infection, tube migration, diarrhea, abdominal bloating, and increased use of physical/chemical restraints to prevent the patient from pulling the tube. Instead, **careful hand-feeding (assisted oral feeding)** should be continued, focusing on patient comfort and flavor preferences. Palliative care consultation is highly valuable to support the family. (Ref: Hazzard''s Ch. 82; AGS Feeding Tubes Position Statement; UWorld Step 2 CK)'),
    (v_topic_id, 'A 94-year-old female named Jean with advanced dementia (FAST stage 7c) is admitted to the hospital with a third episode of aspiration pneumonia in the past 4 months. Her spouse is highly distressed, noting that the patient is eating very little, and asks about placing a percutaneous endoscopic gastrostomy (PEG) feeding tube. According to the American Geriatrics Society (AGS) guidelines, which of the following is the most appropriate counseling and clinical recommendation?', '["Advise the family that a PEG tube is legally mandatory once a patient with dementia is unable to meet their daily caloric needs orally", "Suggest starting total parenteral nutrition (TPN) through a central line as a safer and more effective alternative to tube feeding in advanced dementia", "Recommend immediate PEG tube placement to prevent malnutrition, as feeding tubes have been shown to significantly prolong life and prevent decubitus ulcers in advanced dementia", "Recommend continuing careful hand-feeding and comfort-focused care; explain that PEG tube placement in advanced dementia does not prolong survival, reduce the risk of aspiration pneumonia, improve nutritional parameters, or enhance patient comfort", "Recommend a temporary nasogastric (NG) tube for 6 months to see if she recovers her baseline cognitive function and swallowing capacity"]'::jsonb, 3, 'For patients with advanced dementia (FAST stage 7), clinical evidence demonstrates that **percutaneous endoscopic gastrostomy (PEG) feeding tubes do not prolong survival, reduce aspiration risk, improve nutritional status, or enhance comfort**. Feeding tubes are associated with significant complications, including local infection, tube migration, diarrhea, abdominal bloating, and increased use of physical/chemical restraints to prevent the patient from pulling the tube. Instead, **careful hand-feeding (assisted oral feeding)** should be continued, focusing on patient comfort and flavor preferences. Palliative care consultation is highly valuable to support the family. (Ref: Hazzard''s Ch. 82; AGS Feeding Tubes Position Statement; UWorld Step 2 CK)'),
